def subset(nums, n):
    # Initialize a list to store the result
    dp = [0] * (n + 1)
    # Base case: if n is 0, the minimum number of subsets is 1
    dp[0] = 1

    # Iterate through each number in the input list
    for i in range(1, n + 1):
        # For each number, check if it can be included in any of the previous subsets
        for j in range(i):
            if nums[j] <= nums[i]:
                dp[i] += dp[j]

    # The result is the minimum number of subsets
    return dp[n]

